struct PresetDef
{
    const char* name;
    const char* category;
    int macroTemplate;
    std::vector<std::pair<const char*, float>> values;
};

inline const juce::StringArray& presetCategories()
{
    static const juce::StringArray c { "Pads", "Keys", "Leads", "Bass", "Plucks", "Arps", "Video", "Weird" };
    return c;
}

